python3 - <<'EOF'
import json,re
raw=open('/tmp/ms-all.json').read()
dec=json.JSONDecoder()
items=[];idx=0
while idx<len(raw):
    while idx<len(raw) and raw[idx] not in '[{': idx+=1
    if idx>=len(raw):break
    try:
        obj,end=dec.raw_decode(raw,idx); idx=end
        if isinstance(obj,list): items+=obj
        elif isinstance(obj,dict): items.append(obj)
    except Exception: idx+=1
seen={}
for m in items:
    t=m['title']
    if re.match(r'Go1\.(2[0-9]|[ intending]|3[0-9])',t) or 'Go1.27' in t or 'Go1.2' in t:
        seen[t]=(m['number'],m['open_issues'],m['closed_issues'],m['state'])
for t in sorted(seen,key=lambda x:[int(p) if p.isdigit() else 0 for p in re.split(r'\D',x)]): print(seen[t],t)
EOF

